begin;
create table app.attention_policies(school_id uuid not null,id uuid not null default gen_random_uuid(),version integer not null check(version>0),minimum_decline numeric not null check(minimum_decline>0),max_score numeric not null check(max_score>0),missing_due_count integer not null check(missing_due_count between 1 and 100),window_days integer not null check(window_days between 1 and 365),approved_by uuid not null,approved_at timestamptz not null default clock_timestamp(),primary key(school_id,id),unique(school_id,version),foreign key(school_id,approved_by)references app.memberships(school_id,actor_id));
create table app.attention_signal_revisions(school_id uuid not null,id uuid not null default gen_random_uuid(),learner_id uuid not null,type text not null check(type in('native_result_decline','missing_due_work')),policy_version integer not null,context jsonb not null,source_fingerprint text not null,generated_at timestamptz not null default clock_timestamp(),primary key(school_id,id),unique(school_id,learner_id,type,policy_version,source_fingerprint),foreign key(school_id,learner_id)references app.memberships(school_id,actor_id));
create table app.current_attention_signals(school_id uuid not null,learner_id uuid not null,type text not null,signal_id uuid not null,primary key(school_id,learner_id,type),foreign key(school_id,signal_id)references app.attention_signal_revisions(school_id,id));
create function internal.attention_policy_command(payload jsonb,command_key text,fingerprint text,request_id text)returns jsonb language plpgsql security definer set search_path=''as $$declare school uuid:="authorization".school_id();version integer;rid uuid;reservation jsonb;receipt jsonb;begin
 if not"authorization".has_entitlement(school,'learner.state')or"authorization".current_role(school)<>'admin'then raise exception 'Attention policy approval denied'using errcode='42501';end if;
 if(payload->>'confirmApproval')::boolean is distinct from true or(payload->>'minimumDecline')::numeric<=0 or(payload->>'maxScore')::numeric<=0 then raise exception 'Attention native policy invalid'using errcode='22023';end if;
 reservation:=internal.begin_command(command_key,'attention.policy',fingerprint);if reservation->>'state'='COMPLETED'then return reservation->'response';end if;
 perform pg_advisory_xact_lock(hashtextextended(school::text||':attention-policy',0));select coalesce(max(p.version),0)into version from app.attention_policies p where p.school_id=school;if version<>(payload->>'expectedVersion')::integer then raise exception 'Attention policy version changed'using errcode='22023';end if;
 insert into app.attention_policies(school_id,version,minimum_decline,max_score,missing_due_count,window_days,approved_by)values(school,version+1,(payload->>'minimumDecline')::numeric,(payload->>'maxScore')::numeric,(payload->>'missingDueCount')::integer,(payload->>'windowDays')::integer,"authorization".actor_id())returning id into rid;
 receipt:=jsonb_build_object('id',rid,'version',version+1);perform internal.append_audit('attention.policy','attention_policy',rid,request_id,'succeeded','{}');perform internal.finish_command(command_key,'attention.policy',fingerprint,receipt);return receipt;
end$$;
create function internal.refresh_native_attention(target_school uuid,target_learner uuid)returns void language plpgsql security definer set search_path=''as $$
declare policy app.attention_policies;recent app.result_revisions;baseline app.result_revisions;reference app.school_custom_references;native_context jsonb;missing_context jsonb;missing_rows jsonb;events jsonb;start_at timestamptz;rid uuid;hash text;
begin
 select*into policy from app.attention_policies where school_id=target_school order by version desc limit 1;if not found then return;end if;
 if not exists(select 1 from app.schools where id=target_school and status='active')or not exists(select 1 from app.entitlements where school_id=target_school and code='learner.state'and enabled and effective_from<=now()and(effective_to is null or effective_to>now()))then return;end if;
 perform pg_advisory_xact_lock(hashtextextended(target_school::text||':attention:'||target_learner::text,0));start_at:=clock_timestamp()-make_interval(days=>policy.window_days);
 select r.*into recent from app.current_results c join app.result_revisions r on r.school_id=c.school_id and r.id=c.result_id join app.school_custom_references ref on ref.school_id=r.school_id and ref.id=r.reference_id join app.school_custom_versions version on version.school_id=ref.school_id and version.id=ref.version_id where r.school_id=target_school and r.learner_id=target_learner and r.max_score=policy.max_score and r.created_at>=start_at and version.source_type='SCHOOL_AUTHORED'and ref.status='APPROVED'and version.version=r.reference_version and exists(select 1 from internal.processed_events pe where pe.school_id=r.school_id and pe.source_type='RESULT'and pe.source_id=r.id)order by r.created_at desc,r.id desc limit 1;
 if recent.id is not null then select r.*into baseline from app.current_results c join app.result_revisions r on r.school_id=c.school_id and r.id=c.result_id where r.school_id=recent.school_id and r.learner_id=recent.learner_id and r.reference_id=recent.reference_id and r.reference_version=recent.reference_version and r.max_score=recent.max_score and r.assessment_id<>recent.assessment_id and r.created_at>=start_at and r.created_at<recent.created_at and exists(select 1 from internal.processed_events pe where pe.school_id=r.school_id and pe.source_type='RESULT'and pe.source_id=r.id)order by r.created_at desc,r.id desc limit 1;end if;
 if baseline.id is not null and baseline.score-recent.score>=policy.minimum_decline then
  select coalesce(jsonb_agg(event_id),'[]'::jsonb)into events from internal.processed_events where school_id=target_school and source_type='RESULT'and source_id in(baseline.id,recent.id);
  native_context:=jsonb_build_object('referenceId',recent.reference_id,'referenceVersion',recent.reference_version,'baselineResultId',baseline.id,'followUpResultId',recent.id,'evidenceIds',jsonb_build_array(baseline.evidence_id,recent.evidence_id),'baseline',jsonb_build_object('score',baseline.score,'maxScore',baseline.max_score),'followUp',jsonb_build_object('score',recent.score,'maxScore',recent.max_score),'difference',recent.score-baseline.score,'minimumDecline',policy.minimum_decline,'sourceEventIds',events,'uncertainty','OBSERVED_CHANGE_NOT_CAUSE');
  hash:=md5(native_context::text);select id into rid from app.attention_signal_revisions where school_id=target_school and learner_id=target_learner and type='native_result_decline'and policy_version=policy.version and source_fingerprint=hash;if rid is null then insert into app.attention_signal_revisions(school_id,learner_id,type,policy_version,context,source_fingerprint)values(target_school,target_learner,'native_result_decline',policy.version,native_context,hash)returning id into rid;end if;insert into app.current_attention_signals(school_id,learner_id,type,signal_id)values(target_school,target_learner,'native_result_decline',rid)on conflict(school_id,learner_id,type)do update set signal_id=excluded.signal_id;
 else delete from app.current_attention_signals where school_id=target_school and learner_id=target_learner and type='native_result_decline';end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',a.id,'title',a.title,'dueAt',a.due_at)order by a.due_at,a.id),'[]'::jsonb)into missing_rows from app.assessments a join app.courses course on course.school_id=a.school_id and course.id=a.course_id join app.enrollments e on e.school_id=course.school_id and e.class_id=course.class_id join app.school_custom_references ref on ref.school_id=a.school_id and ref.id=a.academic_reference_id join app.school_custom_versions version on version.school_id=ref.school_id and version.id=ref.version_id where a.school_id=target_school and e.student_actor_id=target_learner and course.status='PUBLISHED'and a.assignment_state='OPEN'and(a.available_from is null or a.available_from<=clock_timestamp())and(a.available_until is null or a.available_until>clock_timestamp())and e.status='active'and e.effective_from<=now()and(e.effective_to is null or e.effective_to>now())and a.due_at<clock_timestamp()and a.due_at>=start_at and version.source_type='SCHOOL_AUTHORED'and ref.status='APPROVED'and"authorization".programme_course_allowed(target_school,course.id,target_learner)and exists(select 1 from app.memberships learner_member where learner_member.school_id=target_school and learner_member.actor_id=target_learner and learner_member.role='student'and learner_member.status='active'and learner_member.effective_from<=now()and(learner_member.effective_to is null or learner_member.effective_to>now()))and not exists(select 1 from app.submissions s where s.school_id=a.school_id and s.assessment_id=a.id and s.learner_id=target_learner);
 if jsonb_array_length(missing_rows)>=policy.missing_due_count then
  if jsonb_array_length(missing_rows)>100 then raise exception 'Missing work attention requires smaller scope'using errcode='22023';end if;
  missing_context:=jsonb_build_object('count',jsonb_array_length(missing_rows),'missingAssessments',missing_rows,'sourceEventIds','[]'::jsonb,'uncertainty','MISSING_SUBMISSION_NOT_ZERO');hash:=md5(missing_context::text);rid:=null;select id into rid from app.attention_signal_revisions where school_id=target_school and learner_id=target_learner and type='missing_due_work'and policy_version=policy.version and source_fingerprint=hash;if rid is null then insert into app.attention_signal_revisions(school_id,learner_id,type,policy_version,context,source_fingerprint)values(target_school,target_learner,'missing_due_work',policy.version,missing_context,hash)returning id into rid;end if;insert into app.current_attention_signals(school_id,learner_id,type,signal_id)values(target_school,target_learner,'missing_due_work',rid)on conflict(school_id,learner_id,type)do update set signal_id=excluded.signal_id;
 else delete from app.current_attention_signals where school_id=target_school and learner_id=target_learner and type='missing_due_work';end if;
end$$;
create function internal.refresh_attention_command(target_learner uuid,expected_policy integer,command_key text,fingerprint text,request_id text)returns jsonb language plpgsql security definer set search_path=''as $$declare reservation jsonb;receipt jsonb;begin
 if not"authorization".has_entitlement("authorization".school_id(),'learner.state')or"authorization".current_role("authorization".school_id())not in('admin','coordinator','teacher')or not"authorization".can_view_person("authorization".school_id(),target_learner)then raise exception 'Attention learner denied'using errcode='42501';end if;
 if expected_policy is null or expected_policy<>(select max(version)from app.attention_policies where school_id="authorization".school_id())then raise exception 'Attention policy unavailable'using errcode='22023';end if;
 reservation:=internal.begin_command(command_key,'attention.refresh',fingerprint);if reservation->>'state'='COMPLETED'then return reservation->'response';end if;perform internal.refresh_native_attention("authorization".school_id(),target_learner);receipt:=jsonb_build_object('id',target_learner,'status','REFRESHED');perform internal.append_audit('attention.refresh','learner',target_learner,request_id,'succeeded','{}');perform internal.finish_command(command_key,'attention.refresh',fingerprint,receipt);return receipt;
end$$;
create function internal.read_attention_signals(page_limit integer,page_cursor uuid,target_learner uuid)returns jsonb language plpgsql security definer set search_path=''as $$declare school uuid:="authorization".school_id();rows jsonb;begin
 if not"authorization".has_entitlement(school,'learner.state')or"authorization".current_role(school)not in('admin','coordinator','teacher','student')or page_limit not between 1 and 100 then raise exception 'Attention read denied'using errcode='42501';end if;
 if target_learner is not null and not"authorization".can_view_person(school,target_learner)then raise exception 'Attention scope denied'using errcode='42501';end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',r.id,'learnerId',r.learner_id,'type',r.type,'ruleVersion',r.policy_version,'generatedAt',r.generated_at)||r.context order by r.id),'[]'::jsonb)into rows from(select revision.*from app.current_attention_signals current_signal join app.attention_signal_revisions revision on revision.school_id=current_signal.school_id and revision.id=current_signal.signal_id where revision.school_id=school and(target_learner is null or revision.learner_id=target_learner)and(page_cursor is null or revision.id>page_cursor)and"authorization".can_view_person(school,revision.learner_id)order by revision.id limit page_limit+1)r;
 return jsonb_build_object('items',(select coalesce(jsonb_agg(item),'[]'::jsonb)from jsonb_array_elements(rows)with ordinality value(item,ordinal)where ordinal<=page_limit),'nextCursor',case when jsonb_array_length(rows)>page_limit then rows->(page_limit-1)->>'id'else null end);
end$$;
do $$declare tab text;begin foreach tab in array array['attention_policies','attention_signal_revisions','current_attention_signals']loop execute format('alter table app.%I enable row level security',tab);execute format('alter table app.%I force row level security',tab);execute format('revoke all on app.%I from public,anon,authenticated,service_role,cuevo_api,cuevo_worker',tab);end loop;end$$;
create trigger attention_policy_immutable before update or delete on app.attention_policies for each row execute function internal.academic_history_immutable();
create trigger attention_revision_immutable before update or delete on app.attention_signal_revisions for each row execute function internal.academic_history_immutable();
revoke execute on function internal.attention_policy_command(jsonb,text,text,text),internal.refresh_native_attention(uuid,uuid),internal.refresh_attention_command(uuid,integer,text,text,text),internal.read_attention_signals(integer,uuid,uuid)from public,anon,authenticated,service_role,cuevo_api,cuevo_worker;
grant execute on function internal.attention_policy_command(jsonb,text,text,text),internal.refresh_attention_command(uuid,integer,text,text,text),internal.read_attention_signals(integer,uuid,uuid)to cuevo_api;
commit;

